class Comparable(object):
    """A mixin that allows objects to be compared."""

    def __eq__(self, other):
        """Return True if the objects are equal."""
        return self.similarity(other) == 1

    def __ne__(self, other):
        """Return True if the objects are not equal."""
        return self.similarity(other) != 1

    def __lt__(self, other):
        """Return True if the object is less than the other."""
        return self.similarity(other) < 1

    def __le__(self, other):
        """Return True if the object is less than or equal to the other."""
        return self.similarity(other) <= 1

    def __gt__(self, other):
        """Return True if the object is greater than the other."""
        return self.similarity(other) > 1

    def __ge__(self, other):
        """Return True if the object is greater than or equal to the other."""
        return self.similarity(other) >= 1

    def __hash__(self):
        """Return a hash of the object."""
        return hash(self.to_string())

    def to_string(self):
        """Return a string representation of the object."""
        return str(self)

    def similarity(self, other):
        """Return a similarity score between 0 and 1."""
        raise NotImplementedError("Must be implemented by subclasses.")


