def watch_log_for_death(self, nodes, from_mark=None, timeout=720, filename='system.log'):
    """
    Watch the log of this node until it detects that the provided other
    nodes are marked DOWN.

    @param nodes: a list of nodes to watch for death
    @param from_mark: if provided, only look for deaths after this mark
    @param timeout: how long to wait for the deaths
    @param filename: the name of the log file to watch
    """
    if not isinstance(nodes, list):
        nodes = [nodes]

    if from_mark is None:
        from_mark = self.mark_log()

    def check_for_deaths():
        for node in nodes:
            if node.is_up():
                return False
        return True

    return self.watch_log_for_marker(from_mark, check_for_deaths, timeout, filename)

def watch_log_for_marker(self, from_mark, check_for_marker, timeout, filename='system.log'):
    """
