    @param check_for_marker: a function that returns True if the marker has been found
    @param timeout: how long to wait for the deaths
    @param filename: the name of the log file to watch
    """
    if from_mark is None:
        from_mark = self.mark_log()

    def check_for_marker_in_log():
        return self.grep_log_for_marker(from_mark, filename)

    return self.watch_log_for_condition(check_for_marker, check_for_marker_in_log, timeout, filename)

