def tokenize(self, text):
    """This is the main tokenizer function."""
    tokens = []
    for word in text.split():
        tokens += self.tokenize_sign(word)
        tokens += self.tokenize_word(word)
        tokens += self.tokenize_number(word)
        tokens += self.tokenize_punctuation(word)
        tokens += self.tokenize_other(word)
    return tokens

def tokenize_sentence(self, sentence):
    """This is for tokenizing sentences."""
    tokens = []
    for word in sentence.split():
        tokens += self.tokenize_sign(word)
        tokens += self.tokenize_word(word)
        tokens += self.tokenize_number(word)
        tokens += self.tokenize_punctuation(word)
        tokens += self.tokenize_other(word)
    return tokens

def tokenize_paragraph(self, paragraph):
    """This is for tokenizing paragraphs."""
    tokens = []
    for sentence in paragraph.split('\n'):
        tokens += self.tokenize_sentence(sentence)
    return tokens

